    'Every project deepens our understanding of the operational realities specific to each industry.' => ['es' => 'Cada proyecto profundiza nuestra comprension de las realidades operativas propias de cada industria.', 'it' => 'Ogni progetto approfondisce la nostra comprensione delle realta operative specifiche di ogni settore.', 'zh' => '每个项目都加深我们对各行业运营现实的理解。'],
    'Let us design your next digital solution' => ['es' => 'Disenemos su proxima solucion digital', 'it' => 'Progettiamo la vostra prossima soluzione digitale', 'zh' => '让我们设计您的下一个数字解决方案'],
    'Every project in this portfolio started with a conversation about a real operational challenge.' => ['es' => 'Cada proyecto de este portafolio comenzo con una conversacion sobre un desafio operativo real.', 'it' => 'Ogni progetto in questo portfolio e iniziato con una conversazione su una reale sfida operativa.', 'zh' => '此作品集中的每个项目都始于一次关于真实运营挑战的对话。'],
    'If your organization is facing one, we can discuss it and share how a similar solution might apply to your context.' => ['es' => 'Si su organizacion enfrenta uno, podemos conversarlo y compartir como una solucion similar podria aplicarse a su contexto.', 'it' => 'Se la vostra organizzazione ne affronta una, possiamo discuterne e condividere come una soluzione simile potrebbe applicarsi al vostro contesto.', 'zh' => '如果您的组织正面临类似问题，我们可以讨论并分享类似方案如何适用于您的场景。'],
    "Modernize the organization's digital identity to reflect its role and standing." => ['es' => 'Modernizar la identidad digital de la organizacion para reflejar su rol y posicion.', 'it' => 'Modernizzare l identita digitale dell organizzazione per rifletterne ruolo e posizionamento.', 'zh' => '现代化组织的数字身份，以体现其角色和地位。'],
    "DigiTexia continuously invests in innovation to build digital solutions that address Africa's evolving operational realities: scalable technologies designed for long-term impact, not short-term novelty." => ['es' => 'DigiTexia invierte continuamente en innovacion para construir soluciones digitales que respondan a las realidades operativas cambiantes de Africa: tecnologias escalables disenadas para impacto a largo plazo, no novedad de corto plazo.', 'it' => 'DigiTexia investe continuamente in innovazione per costruire soluzioni digitali che affrontano le realta operative africane in evoluzione: tecnologie scalabili progettate per impatto a lungo termine, non novita di breve periodo.', 'zh' => 'DigiTexia 持续投资创新，构建应对非洲不断变化运营现实的数字解决方案：为长期影响而设计的可扩展技术，而不是短期新奇功能。'],
];

$translations = ['es' => [], 'it' => [], 'zh' => []];
foreach ($base as $key => $values) {
    foreach ($translations as $locale => $_) {
        $translations[$locale][$key] = $values[$locale];
    }
}

foreach ($translations as $locale => $entries) {
    $path = $root . "/resources/lang/{$locale}.json";
    $json = json_decode(file_get_contents($path), true) ?: [];
    foreach ($entries as $key => $value) {
        $json[$key] = $value;
    }
    ksort($json, SORT_NATURAL | SORT_FLAG_CASE);
    file_put_contents($path, json_encode($json, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . PHP_EOL);
}

echo "projects ES/IT/ZH translations fixed\n";
